mapper.select:
select o.order_id, o.order_no, o.member_id, o.product_id, o.product_type, o.product_title, o.product_cover,
       o.unit_price, o.quantity, o.amount, o.pay_amount, o.status, o.pay_type, o.pay_time, o.travel_date,
       o.contact_name, o.contact_phone, o.remark, o.ship_time, o.finish_time, o.refund_time, o.refund_reason,
       o.after_sale, o.create_time, o.update_time, m.nickname as member_name, m.phone as member_phone
from hys_order o
left join hys_member m on m.member_id = o.member_id

    and o.member_id = #{memberId}
    and o.status = #{status}
    and o.product_type = #{productType}
    and o.order_no like concat('%', #{orderNo}, '%')

        and o.status in
        #{st}


        and o.create_time >= #{params.beginTime}


        and o.create_time <= concat(#{params.endTime}, ' 23:59:59')


order by o.order_id desc

mapper.update:
update hys_order
product_title = #{productTitle}, remark = #{remark}, ship_time = #{shipTime}, finish_time = #{finishTime}, update_time = now()
where order_id = #{orderId}
